import{A as e,f as t,h as n,t as r}from"./chunks/plugin-vue_export-helper.I53torQa.js";var i=JSON.parse(`{"title":"昇腾 910B3 硬件架构与 CANN 软件栈","description":"以一份 Ascend 910B3 服务器环境记录为线索，介绍达芬奇计算架构、存储与数据搬运、CANN 软件组件及开发工具，区分设备观测、通用原理和版本相关能力，为训练与推理适配提供基础。","frontmatter":{"title":"昇腾 910B3 硬件架构与 CANN 软件栈","description":"以一份 Ascend 910B3 服务器环境记录为线索，介绍达芬奇计算架构、存储与数据搬运、CANN 软件组件及开发工具，区分设备观测、通用原理和版本相关能力，为训练与推理适配提供基础。"},"headers":[],"relativePath":"ascend/architecture/ascend-910b3-cann-architecture.md","filePath":"ascend/architecture/ascend-910b3-cann-architecture.md","lastUpdated":1793959026000}`),a={name:`ascend/architecture/ascend-910b3-cann-architecture.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="昇腾-910b3-硬件架构与-cann-软件栈" tabindex="-1">昇腾 910B3 硬件架构与 CANN 软件栈 <a class="header-anchor" href="#昇腾-910b3-硬件架构与-cann-软件栈" aria-label="Permalink to “昇腾 910B3 硬件架构与 CANN 软件栈”">​</a></h1><p>理解昇腾平台，需要把计算单元、存储与数据搬运、运行时和框架适配连接起来。本文以原稿记录的一台八卡 Ascend 910B3 服务器为线索，先解释硬件如何组织计算，再介绍 CANN 各组件如何支持算子执行与分布式训练。</p><blockquote><p><strong>资料范围</strong>：文中的服务器参数与测量值来自原始环境记录，本次整理未连接设备复测，原始命令输出、测试配置和测量日期尚未附全。这些数值不代表所有 910B3 设备的规格或性能，更不能直接套用于 910C。软硬件能力和安装路径应以目标产品、CANN 版本及兼容性文档为准。</p></blockquote><p>相关阅读：<a href="https://jianzhnie.github.io/llmtechsite/ascend/architecture/" target="_blank" rel="noreferrer">昇腾软硬件架构与资料导读</a>。</p><h2 id="_1-硬件架构-ascend-910b3" tabindex="-1">1. 硬件架构: Ascend 910B3 <a class="header-anchor" href="#_1-硬件架构-ascend-910b3" aria-label="Permalink to “1. 硬件架构: Ascend 910B3”">​</a></h2><h3 id="_1-1-概述" tabindex="-1">1.1 概述 <a class="header-anchor" href="#_1-1-概述" aria-label="Permalink to “1.1 概述”">​</a></h3><p>Ascend 910B3 是华为昇腾系列 AI 处理器，采用达芬奇（Da Vinci）架构。原始记录中的服务器配备 8 张 910B3 卡，设备间连接类型标记为 HCCS。连接可达性、物理链路和集合通信性能需要分别核对。</p><p>原始服务器环境与测量记录：</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>型号</td><td>Ascend 910B3</td></tr><tr><td>HBM 容量/卡</td><td>64 GB (65536 MB)</td></tr><tr><td>HBM 频率</td><td>1600 MHz</td></tr><tr><td>HBM 厂商 ID</td><td>0x57（原稿标注为 Samsung，厂商映射待核实）</td></tr><tr><td>卡间互联</td><td>记录中的八卡设备对均标记为 HCCS</td></tr><tr><td>HCCS 单链路 lane 数</td><td>4</td></tr><tr><td>典型功耗</td><td>~90-97 W（空闲）/ ~231 W（FP16 算力满载）/ ~273 W（实测训练满载）/ ~300 W（原稿标注为 TDP，需核对板卡规格）</td></tr><tr><td>空闲温度</td><td>34-40°C</td></tr><tr><td>驱动版本</td><td>24.1.0.3</td></tr></tbody></table></div><p>原稿记录的卡间连接类型矩阵如下。原稿标注命令为 <code>npu-smi info -l</code>，但该选项在常见版本中用于设备枚举；复现时应通过目标版本的 <code>npu-smi info -h</code> 核对拓扑查询方式。</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;" tabindex="0" dir="ltr"><code><span class="line"><span>      NPU0  NPU1  NPU2  NPU3  NPU4  NPU5  NPU6  NPU7</span></span>
<span class="line"><span>NPU0   X    HCCS  HCCS  HCCS  HCCS  HCCS  HCCS  HCCS</span></span>
<span class="line"><span>NPU1  HCCS   X    HCCS  HCCS  HCCS  HCCS  HCCS  HCCS</span></span>
<span class="line"><span>NPU2  HCCS  HCCS   X    HCCS  HCCS  HCCS  HCCS  HCCS</span></span>
<span class="line"><span>NPU3  HCCS  HCCS  HCCS   X    HCCS  HCCS  HCCS  HCCS</span></span>
<span class="line"><span>NPU4  HCCS  HCCS  HCCS  HCCS   X    HCCS  HCCS  HCCS</span></span>
<span class="line"><span>NPU5  HCCS  HCCS  HCCS  HCCS  HCCS   X    HCCS  HCCS</span></span>
<span class="line"><span>NPU6  HCCS  HCCS  HCCS  HCCS  HCCS  HCCS   X    HCCS</span></span>
<span class="line"><span>NPU7  HCCS  HCCS  HCCS  HCCS  HCCS  HCCS  HCCS   X</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>该矩阵表明记录中的设备对被归类为 HCCS 连接，但不能单独证明每对设备均有独占物理直连，也无法推导并发带宽和拥塞行为。评估训练拓扑还需核对服务器布线、链路状态，以及目标通信规模下的实测结果。</p><hr><h3 id="_1-2-达芬奇-da-vinci-架构核心设计" tabindex="-1">1.2 达芬奇 (Da Vinci) 架构核心设计 <a class="header-anchor" href="#_1-2-达芬奇-da-vinci-架构核心设计" aria-label="Permalink to “1.2 达芬奇 (Da Vinci) 架构核心设计”">​</a></h3><p>昇腾的计算资源可按矩阵、向量与标量控制三类职责理解。Cube 执行矩阵乘加，Vector 处理逐元素运算、归约及激活等操作，Scalar 负责地址计算和控制流。</p><p>910B 系列的算子编程还需要理解矩阵计算资源 AIC 与向量计算资源 AIV 的分离组织。不能将早期达芬奇架构中“三种单元位于同一核心”的示意图，直接当成所有型号的物理布局；具体核数、资源配比和同步能力应查阅对应产品文档。</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>资源或职责</th><th>典型任务</th><th>与 GPU 的功能类比及边界</th></tr></thead><tbody><tr><td>Cube / AIC</td><td>矩阵乘加、GEMM</td><td>可类比 Tensor Core 的矩阵加速职责，执行模型不等同</td></tr><tr><td>Vector / AIV</td><td>激活、归约、逐元素处理</td><td>不能简单视为一组 CUDA Core，任务组织与指令接口不同</td></tr><tr><td>Scalar</td><td>控制流、地址和标量计算</td><td>属于控制与标量处理职责，不对应独立的 CUDA 软件层</td></tr></tbody></table></div><p>架构对性能的直接影响，是算子需要组织好矩阵计算、向量计算和数据搬运之间的依赖与重叠。是否提高利用率或能效，取决于工作负载与实现，不能仅凭资源分工判定优于 GPU。</p><h3 id="_1-3-内存层次" tabindex="-1">1.3 内存层次 <a class="header-anchor" href="#_1-3-内存层次" aria-label="Permalink to “1.3 内存层次”">​</a></h3><p>存储系统应按计算和搬运路径理解，而不是画成所有数据必须逐层经过的单一缓存链：</p><ul><li><strong>HBM / GM</strong>：HBM 是物理高带宽内存，GM 是算子编程中的全局内存视角。原始记录中单卡容量为 64 GB。</li><li><strong>L2 Cache</strong>：服务设备全局访存的共享缓存，其命中行为与软件显式管理的局部缓冲区不同。</li><li><strong>L1 与 L0A/L0B/L0C</strong>：用于矩阵数据准备、输入与累加结果等，具体职责和访问路径由目标架构决定。</li><li><strong>Unified Buffer（UB）</strong>：向量计算使用的重要局部存储，不能从存储图中省略，也不应概括为“Vector 的 L0”。</li><li><strong>MTE（Memory Transfer Engine）</strong>：承担支持路径上的数据搬运；高性能算子通过分块和流水线，将搬运与计算重叠，并显式处理依赖。</li></ul><p>原稿记录 <code>ascend-dmi --bw -t d2d</code> 测得约 1538 GB/s，并将其解释为 HBM 带宽。该解释需要补充工具版本、测试说明、数据规模和计时口径后核实：D2D 命名本身不能证明测得的就是 HBM 硬件带宽。因此本文将其保留为待核对的测试记录，不作为产品带宽规格或跨平台对比依据。</p><blockquote><p>注：CANN 的商业版本号和内部版本号需要区分。本服务器上的 CANN 商业版本为 8.0.1（对应 <code>ascend-toolkit</code> 目录名），但 runtime/compiler/hccl 等内部组件版本号均为 7.6.0.2.220（即 <code>7.6</code> 系列）。在查阅版本兼容性矩阵时需注意这个区分。</p></blockquote><hr><h2 id="_2-cann-软件栈" tabindex="-1">2. CANN 软件栈 <a class="header-anchor" href="#_2-cann-软件栈" aria-label="Permalink to “2. CANN 软件栈”">​</a></h2><p>CANN 是连接框架与昇腾硬件的重要软件平台，提供运行时、编译、算子与通信等能力。驱动和固件与 CANN 配套协作，但属于需要单独核对兼容性的组件。下面的层次图用于说明职责，不表示所有任务都严格依次经过每一层。</p><h3 id="_2-1-栈全貌" tabindex="-1">2.1 栈全貌 <a class="header-anchor" href="#_2-1-栈全貌" aria-label="Permalink to “2.1 栈全貌”">​</a></h3><p>CANN (Compute Architecture for Neural Networks) 是华为昇腾的异构计算架构，类似于 NVIDIA 的 CUDA 平台 + 工具链集合。</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;" tabindex="0" dir="ltr"><code><span class="line"><span>┌──────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  开发框架层                                    │</span></span>
<span class="line"><span>│  MindSpore / PyTorch (torch_npu) / TensorFlow│</span></span>
<span class="line"><span>├──────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  应用开发层                                    │</span></span>
<span class="line"><span>│  AscendCL (C/Python API)                     │</span></span>
<span class="line"><span>├──────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  图编译与优化层                                │</span></span>
<span class="line"><span>│  GE (Graph Engine) / AOE（自动调优工具）    │</span></span>
<span class="line"><span>├──────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  算子层                                       │</span></span>
<span class="line"><span>│  Ascend C / TBE / AI CPU 算子 + 内置算子库     │</span></span>
<span class="line"><span>│  (OPP: Operator Plugin Package)              │</span></span>
<span class="line"><span>├──────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  运行时层 (Runtime)                           │</span></span>
<span class="line"><span>│  任务调度 / 内存管理 / Stream 管理              │</span></span>
<span class="line"><span>├──────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  任务调度层 (Task Scheduler / TSC)             │</span></span>
<span class="line"><span>├──────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  驱动层 (Driver)                              │</span></span>
<span class="line"><span>│  设备管理 / 固件通信 / PCIe 驱动                │</span></span>
<span class="line"><span>├──────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  硬件层                                       │</span></span>
<span class="line"><span>│  Ascend 910B3 / 310P / 710 等                 │</span></span>
<span class="line"><span>└──────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br></div></div><h3 id="_2-2-各层详解" tabindex="-1">2.2 各层详解 <a class="header-anchor" href="#_2-2-各层详解" aria-label="Permalink to “2.2 各层详解”">​</a></h3><h4 id="_2-2-1-驱动层-driver" tabindex="-1">2.2.1 驱动层 (Driver) <a class="header-anchor" href="#_2-2-1-驱动层-driver" aria-label="Permalink to “2.2.1 驱动层 (Driver)”">​</a></h4><p>最底层，负责：</p><ul><li>与固件 (Firmware v7.5.0.5.220) 通信</li><li>PCIe 设备管理（<code>/dev/davinci0</code> ~ <code>/dev/davinci7</code>）</li><li>内存映射、DMA 传输</li><li>通过 <code>npu-smi</code> 工具导出设备状态</li></ul><p>当前服务器驱动版本：24.1.0.3</p><h4 id="_2-2-2-运行时层-runtime" tabindex="-1">2.2.2 运行时层 (Runtime) <a class="header-anchor" href="#_2-2-2-运行时层-runtime" aria-label="Permalink to “2.2.2 运行时层 (Runtime)”">​</a></h4><p>可从功能上类比 CUDA Runtime 的部分职责。负责任务分发到 AI Core/AI CPU、设备内存管理、Stream 与 Event 管理。Runtime 下层是任务调度层（Task Scheduler, TSC），负责将计算任务派发到具体 AI Core，通常由上层框架与运行时接口封装，排查性能问题时仍可能需要关注其调度开销。</p><h4 id="_2-2-3-算子层-operator-layer" tabindex="-1">2.2.3 算子层 (Operator Layer) <a class="header-anchor" href="#_2-2-3-算子层-operator-layer" aria-label="Permalink to “2.2.3 算子层 (Operator Layer)”">​</a></h4><p>使用 CANN 算子时，应区分“调用已有算子”和“开发自定义算子”，不要将不同技术按固定的高低等级排列。</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>方式</th><th>作用</th><th>选择依据</th></tr></thead><tbody><tr><td>内置算子与算子包</td><td>提供目标产品和版本支持的算子实现</td><td>优先检查已有实现是否覆盖精度、形状和布局</td></tr><tr><td>Ascend C</td><td>使用 C/C++ 风格接口组织计算、搬运和同步</td><td>需要自定义逻辑或针对工作负载优化时采用</td></tr><tr><td>TBE（Tensor Boost Engine）</td><td>基于 DSL 等机制描述和生成算子</td><td>按既有实现、版本支持及迁移成本选择</td></tr></tbody></table></div><p>OPP（Operator Package）提供算子相关资源，安装布局随版本变化。原环境中的路径为 <code>/usr/local/Ascend/ascend-toolkit/latest/opp/</code>，不能假定所有安装均采用相同目录。</p><p>CUDA 生态同样包含算子库、编译器与多种编程接口。两者都应按实际调用路径选择工具，不宜概括为“CUDA 只有一种模型、CANN 有三个优化等级”。</p><h4 id="_2-2-4-图编译与优化层" tabindex="-1">2.2.4 图编译与优化层 <a class="header-anchor" href="#_2-2-4-图编译与优化层" aria-label="Permalink to “2.2.4 图编译与优化层”">​</a></h4><ul><li><strong>GE（Graph Engine）</strong>：提供计算图处理、编译和优化能力；是否使用该路径取决于框架和执行模式。它不属于驱动层，也不是所有 PyTorch eager 算子执行的必经阶段。</li><li><strong>AOE（Ascend Optimization Engine）</strong>：用于支持场景下的自动调优，具体能力以版本文档为准。</li></ul><p>图编译、算子编译与运行时调度解决不同问题。GPU 生态也有框架编译器和推理优化工具，不能将两者简化为“一个有图编译，另一个没有”。</p><h4 id="_2-2-5-ascendcl-ascend-computing-language" tabindex="-1">2.2.5 AscendCL (Ascend Computing Language) <a class="header-anchor" href="#_2-2-5-ascendcl-ascend-computing-language" aria-label="Permalink to “2.2.5 AscendCL (Ascend Computing Language)”">​</a></h4><p>应用开发 API 层，提供 C/Python 接口。功能包括：</p><ul><li>设备/Context/Stream 管理</li><li>模型加载与推理执行</li><li>媒体数据预处理（图像编解码、缩放等，即 DVPP 模块）</li><li>单算子调用</li></ul><p>框架适配层会使用 CANN 的算子与运行时等接口，不同执行路径不一定经过相同 API。应用开发者则可根据需要直接使用 AscendCL。</p><h4 id="_2-2-6-hccl-huawei-collective-communication-library" tabindex="-1">2.2.6 HCCL (Huawei Collective Communication Library) <a class="header-anchor" href="#_2-2-6-hccl-huawei-collective-communication-library" aria-label="Permalink to “2.2.6 HCCL (Huawei Collective Communication Library)”">​</a></h4><p>集合通信库，对应 NVIDIA 的 <strong>NCCL</strong>。提供：</p><ul><li>AllReduce、AllGather、ReduceScatter、Broadcast 等集合操作</li><li>利用平台支持的 HCCS、网络等通信路径，具体由部署与版本决定</li><li>通信原语和算法实现</li></ul><p>本服务器 HCCL 版本：7.6.0.2.220，8 卡之间通过 HCCS 链路全互联。</p><h4 id="_2-2-7-框架适配层" tabindex="-1">2.2.7 框架适配层 <a class="header-anchor" href="#_2-2-7-框架适配层" aria-label="Permalink to “2.2.7 框架适配层”">​</a></h4><ul><li><strong>torch_npu</strong>：PyTorch 与 CANN 的适配层。为 PyTorch 提供昇腾设备后端及算子适配，不是将任意 CUDA API 或 CUDA kernel 自动转换为 NPU 实现。版本需与 PyTorch 和 CANN 同时兼容。</li><li><strong>MindSpore</strong>：华为自研框架，对 Ascend 有原生支持，不依赖 torch_npu。</li></ul><hr><h2 id="_3-cann-vs-cuda-开发工具对照" tabindex="-1">3. CANN vs CUDA 开发工具对照 <a class="header-anchor" href="#_3-cann-vs-cuda-开发工具对照" aria-label="Permalink to “3. CANN vs CUDA 开发工具对照”">​</a></h2><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>功能</th><th>CANN 工具</th><th>CUDA 工具</th></tr></thead><tbody><tr><td>设备管理</td><td><code>npu-smi</code></td><td><code>nvidia-smi</code></td></tr><tr><td>Profiling</td><td><code>msprof</code></td><td><code>nsys</code> / <code>ncu</code> (Nsight)</td></tr><tr><td>模型转换</td><td><code>atc</code> (Ascend Tensor Compiler)</td><td>TensorRT <code>trtexec</code></td></tr><tr><td>模型压缩</td><td>AMCT</td><td>TensorRT 量化</td></tr><tr><td>算子自动调优</td><td>AOE</td><td>cuDNN autotune</td></tr><tr><td>算子开发</td><td>Ascend C / TBE + <code>msopgen</code></td><td>CUDA C++</td></tr><tr><td>编译工具链</td><td>BiSheng Compiler (<code>ccec</code>)</td><td>NVCC</td></tr><tr><td>调试</td><td><code>msdebug</code></td><td><code>cuda-gdb</code></td></tr><tr><td>分布式通信</td><td>HCCL</td><td>NCCL</td></tr><tr><td>图编译与优化</td><td>GE (Graph Engine)</td><td>torch.compile、TensorRT 等（按场景比较）</td></tr><tr><td>集合通信测试</td><td><code>hccl_test</code></td><td><code>nccl-tests</code></td></tr><tr><td>开发套件路径</td><td><code>/usr/local/Ascend/ascend-toolkit/latest/</code></td><td><code>/usr/local/cuda/</code></td></tr></tbody></table></div><p>上述工具是按用途建立的近似对照，并非能力一一对应。CUDA Graphs 主要用于捕获和重放执行图，与 GE 的图编译职责不同；模型转换、调试和性能工具也需按目标任务核对。</p><p><strong>关键环境变量对照</strong>：</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>CANN</th><th>CUDA</th><th>作用</th></tr></thead><tbody><tr><td><code>ASCEND_RT_VISIBLE_DEVICES</code></td><td><code>CUDA_VISIBLE_DEVICES</code></td><td>可见设备控制</td></tr><tr><td><code>ASCEND_TOOLKIT_HOME</code></td><td><code>CUDA_HOME</code></td><td>工具套件路径</td></tr><tr><td><code>ASCEND_OPP_PATH</code></td><td>(无对应，内置)</td><td>算子包路径</td></tr><tr><td><code>ASCEND_HOME_PATH</code></td><td>(无对应)</td><td>CANN 安装路径</td></tr></tbody></table></div><hr><h2 id="_4-从服务器视角理解-cann-目录结构" tabindex="-1">4. 从服务器视角理解 CANN 目录结构 <a class="header-anchor" href="#_4-从服务器视角理解-cann-目录结构" aria-label="Permalink to “4. 从服务器视角理解 CANN 目录结构”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;" tabindex="0" dir="ltr"><code><span class="line"><span>/usr/local/Ascend/</span></span>
<span class="line"><span>├── driver/           # 驱动 (v24.1.0.3)</span></span>
<span class="line"><span>│   ├── device/       # 设备节点</span></span>
<span class="line"><span>│   ├── lib64/        # 驱动库</span></span>
<span class="line"><span>│   └── version.info</span></span>
<span class="line"><span>├── firmware/         # 固件 (v7.5.0.5.220)</span></span>
<span class="line"><span>├── ascend-toolkit/   # CANN 开发套件</span></span>
<span class="line"><span>│   ├── 8.0.1/        # 版本号</span></span>
<span class="line"><span>│   ├── 8.0/          # 主版本</span></span>
<span class="line"><span>│   ├── latest/  → 8.0.1  # 符号链接</span></span>
<span class="line"><span>│   └── set_env.sh    # 环境变量脚本</span></span>
<span class="line"><span>├── toolbox/          # 工具箱 (npu-smi 等)</span></span>
<span class="line"><span>└── Ascend-Docker-Runtime/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>以下为环境变量用途示意，不是可直接复制执行的脚本。实际使用应加载安装包提供的 <code>set_env.sh</code>，而非手工拼接路径：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;" tabindex="0" dir="ltr"><code><span class="line"><span>ASCEND_TOOLKIT_HOME=/usr/local/Ascend/ascend-toolkit/latest</span></span>
<span class="line"><span>LD_LIBRARY_PATH=$ASCEND_TOOLKIT_HOME/lib64:...</span></span>
<span class="line"><span>PYTHONPATH=$ASCEND_TOOLKIT_HOME/python/site-packages:...</span></span>
<span class="line"><span>PATH=$ASCEND_TOOLKIT_HOME/bin:$ASCEND_TOOLKIT_HOME/compiler/ccec_compiler/bin:...</span></span>
<span class="line"><span>ASCEND_OPP_PATH=$ASCEND_TOOLKIT_HOME/opp</span></span>
<span class="line"><span>ASCEND_AICPU_PATH=$ASCEND_TOOLKIT_HOME</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="_5-编程模型与迁移边界" tabindex="-1">5. 编程模型与迁移边界 <a class="header-anchor" href="#_5-编程模型与迁移边界" aria-label="Permalink to “5. 编程模型与迁移边界”">​</a></h2><p>NVIDIA GPU 主要通过线程、线程块与 warp 组织 SIMT 执行，并使用专门的矩阵计算资源。昇腾算子开发则更需要显式考虑矩阵与向量资源、局部缓冲区、数据分块和流水线同步。两者都包含专用计算资源，差别不能简单归结为“GPU 同构、NPU 异构”。</p><p>迁移 PyTorch 工作负载时，先检查标准算子在目标后端的支持范围、精度和布局要求。自定义 CUDA 扩展通常需要选择已有 NPU 算子替代，或使用 Ascend C 等方式重新实现；不能假定改动设备字符串即可迁移全部逻辑。</p><p>优化时应分别测量计算、数据搬运、通信和主机调度开销。计算资源可以并行，不代表所有任务天然重叠；依赖、同步和缓冲区容量都可能限制流水线。图模式也只是可选择的执行路径，不能将每个任务都描述为“先由 GE 分析，再分发到计算单元”。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to “参考资料”">​</a></h2><ul><li><a href="https://www.hiascend.com/hardware/ai-chip" target="_blank" rel="noreferrer">昇腾社区 — 硬件产品</a></li><li><a href="https://www.hiascend.com/document/detail/en/canncommercial/800/overview/overview/overview_0001.html" target="_blank" rel="noreferrer">CANN 商业版文档 — 软件架构</a></li><li><a href="https://www.hiascend.com/document" target="_blank" rel="noreferrer">昇腾社区 — CANN 概述</a></li><li><a href="https://gitee.com/ascend/pytorch" target="_blank" rel="noreferrer">Ascend PyTorch 适配 (Gitee)</a></li><li><a href="https://www.hiascend.com/document/detail/en/canncommercial/800/devguide/hccl/hccl_0001.html" target="_blank" rel="noreferrer">HCCL 集合通信库文档</a></li></ul>`,72)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};